import java.time.LocalDate;
import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Objects;

public class TemperatureReading {
    private LocalDate date;
    private String location;
    private double temperature;

    public TemperatureReading(LocalDate date, String location, double temperature) {
        this.date = date;
        this.location = location;
        this.temperature = temperature;
    }

    // Getters
    public LocalDate getDate() {
        return date;
    }

    public String getLocation() {
        return location;
    }

    public double getTemperature() {
        return temperature;
    }

    // 1. Method to calculate temperature difference between two instances
    public double temperatureDifference(TemperatureReading other) {
        return Math.abs(this.temperature - other.temperature);
    }

    // 2. Method to find the temperature trend from a list
    public static String getTemperatureTrend(List<TemperatureReading> readings) {
        if (readings == null || readings.size() < 2) {
            return "No trend (insufficient data)";
        }

        readings.sort(Comparator.comparing(TemperatureReading::getDate));

        boolean increasing = true;
        boolean decreasing = true;

        for (int i = 1; i < readings.size(); i++) {
            double prev = readings.get(i - 1).temperature;
            double curr = readings.get(i).temperature;

            if (curr > prev) {
                decreasing = false;
            } else if (curr < prev) {
                increasing = false;
            }
        }

        if (increasing) return "Increasing";
        if (decreasing) return "Decreasing";
        return "No clear trend";
    }

    // 3. Method to find the average temperature for a given location
    public static double getAverageTemperature(List<TemperatureReading> readings, String location) {
        if (readings == null || readings.isEmpty()) {
            return 0.0;
        }

        double sum = 0.0;
        int count = 0;

        for (TemperatureReading reading : readings) {
            if (reading.location.equals(location)) {
                sum += reading.temperature;
                count++;
            }
        }

        return count == 0 ? 0.0 : sum / count;
    }

    // 4. Method to find the hottest and coldest day
    public static TemperatureReading[] getHottestAndColdest(List<TemperatureReading> readings) {
        if (readings == null || readings.isEmpty()) {
            return new TemperatureReading[0];
        }

        TemperatureReading hottest = readings.get(0);
        TemperatureReading coldest = readings.get(0);

        for (TemperatureReading reading : readings) {
            if (reading.temperature > hottest.temperature) {
                hottest = reading;
            }
            if (reading.temperature < coldest.temperature) {
                coldest = reading;
            }
        }

        return new TemperatureReading[]{hottest, coldest};
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        TemperatureReading that = (TemperatureReading) o;
        return Double.compare(temperature, that.temperature) == 0 &&
                date.equals(that.date) &&
                location.equals(that.location);
    }

    @Override
    public int hashCode() {
        return Objects.hash(date, location, temperature);
    }

    @Override
    public String toString() {
        return "TemperatureReading{" +
                "date=" + date +
                ", location='" + location + '\'' +
                ", temperature=" + temperature +
                '}';
    }
}
```

