import org.junit.jupiter.api.Test;
import java.time.LocalDate;
import java.util.List;
import java.util.ArrayList;
import static org.junit.jupiter.api.Assertions.*;

public class TemperatureReadingTest {

    @Test
    public void testTemperatureDifference() {
        TemperatureReading reading1 = new TemperatureReading(LocalDate.of(2023, 1, 1), "Computer City", 25.0);
        TemperatureReading reading2 = new TemperatureReading(LocalDate.of(2023, 1, 2), "Computer City", 30.0);
        assertEquals(5.0, reading1.temperatureDifference(reading2), 0.001);
    }

    @Test
    public void testTemperatureTrend() {
        List<TemperatureReading> readings = new ArrayList<>();
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 1), "Effect Valley", 10.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 2), "Effect Valley", 12.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 3), "Effect Valley", 14.0));
        assertEquals("Increasing", TemperatureReading.getTemperatureTrend(readings));
    }

    @Test
    public void testAverageTemperature() {
        List<TemperatureReading> readings = new ArrayList<>();
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 1), "Funeral Hill", 15.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 2), "Funeral Hill", 20.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 3), "Funeral Hill", 25.0));
        assertEquals(20.0, TemperatureReading.getAverageTemperature(readings, "Funeral Hill"), 0.001);
    }

    @Test
    public void testHottestAndColdest() {
        List<TemperatureReading> readings = new ArrayList<>();
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 1), "Strike Town", 5.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 2), "Strike Town", 15.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 3), "Strike Town", 25.0));
        TemperatureReading[] result = TemperatureReading.getHottestAndColdest(readings);
        assertEquals(25.0, result[0].getTemperature(), 0.001);
        assertEquals(5.0, result[1].getTemperature(), 0.001);
    }

    @Test
    public void testNoTrend() {
        List<TemperatureReading> readings = new ArrayList<>();
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 1), "Computer City", 20.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 2), "Computer City", 18.0));
        readings.add(new TemperatureReading(LocalDate.of(2023, 1, 3), "Computer City", 20.0));
        assertEquals("No clear trend", TemperatureReading.getTemperatureTrend(readings));
    }
}
