#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>

class User {
public:
    int id;
    std::string name;

    User(int id, const std::string& name) : id(id), name(name) {}

    // Overload hash function for unordered_set
    struct Hash {
        size_t operator()(const User& user) const {
            return std::hash<int>()(user.id) ^ (std::hash<std::string>()(user.name) << 1);
        }
    };

    // Overload equality operator
    bool operator==(const User& other) const {
        return id == other.id && name == other.name;
    }
};

std::vector<User> findIntersection(const std::vector<User>& vec1, const std::vector<User>& vec2) {
    std::unordered_set<User, User::Hash> set1(vec1.begin(), vec1.end());
    std::vector<User> result;

    for (const auto& user : vec2) {
        if (set1.find(user) != set1.end()) {
            result.push_back(user);
        }
    }

    return result;
}

// Test cases
int main() {
    std::vector<User> vector1 = {
        User(1, "Alice"),
        User(2, "Bob"),
        User(3, "Charlie")
    };

    std::vector<User> vector2 = {
        User(2, "Bob"),
        User(3, "Charlie"),
        User(4, "David")
    };

    std::vector<User> intersection = findIntersection(vector1, vector2);

    std::cout << "Intersection of vectors:\n";
    for (const auto& user : intersection) {
        std::cout << "ID: " << user.id << ", Name: " << user.name << "\n";
    }

    return 0;
}
